mapper.sql:
INNER JOIN departments d ON de.department_code = d.department_code
    AND d.delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
INNER JOIN employees e ON de.employee_id = e.client_id
AND e.delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

